 page.locator('.review-queue-button').nth(2).click();page.evaluate("()=>{window.__reviewWrites=[];Storage.prototype.setItem=function(k,v){window.__reviewWrites.push(k);throw new DOMException('blocked','QuotaExceededError')}}");grade(page,'Correct');button(page,'Apply sample grade').dblclick();check('Rapid double activation applies one sample response',page.locator('.workspace-count').inner_text()=='11');expect(page.locator('.review-grade-actions')).to_be_focused();check('Apply moves keyboard focus into visible action group',page.locator('.review-grade-actions').evaluate('(e)=>{const r=e.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight}'));check('Sample apply works in memory without attempting a storage write',page.evaluate('window.__reviewWrites.length')==0 and storage(page)==before)
