 page.locator('a[href="/admin"]').first.click();check('Empty shared queue offers content preparation',tr(page,'Prepare content') in page.locator('.authoring-priority').inner_text() and page.locator('.authoring-priority a').get_attribute('href')=='/admin/bank');check('All preview applies preserve student storage',storage(page)==before and page.evaluate('window.__reviewWrites.length')==0)
