 c.close();c=b.new_context(viewport={'width':390,'height':844});c.add_init_script("localStorage.setItem('hm.language','ru')");page=c.new_page();visit(page,'/admin/grading');check('Narrow response queue starts collapsed and remains discoverable',page.locator('.review-queue details').get_attribute('open') is None and page.locator('.review-queue summary').is_visible());page.locator('.review-queue summary').focus();page.keyboard.press('Enter');check('Narrow queue opens with native keyboard disclosure',page.locator('.review-queue details').get_attribute('open') is not None);page.locator('.review-queue-button').nth(3).focus();page.keyboard.press('Enter');expect(page.locator('#response-title')).to_be_focused();check('Narrow queue keyboard selection focuses response with manual guidance',tr(page,'No accepted model is set. Review the meaning using the rubric; an empty model does not imply an incorrect response.') in page.locator('main').inner_text());page.locator('.review-response [role=radio]').first.click();button(page,'Apply sample grade').click();expect(page.locator('.review-grade-actions')).to_be_focused();check('Narrow apply keeps the focused controls visible',page.locator('.review-grade-actions').evaluate('(e)=>{const r=e.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight}'));page.locator('.review-response [role=radio]').nth(1).click();page.locator('.workspace-menu').click();page.locator('nav a[href="/admin/bank"]').click();expect(page.locator('dialog[open]')).to_be_visible();check('Drawer navigation opens only one loss confirmation',page.locator('dialog[open]').count()==1);page.keyboard.press('Escape');page.evaluate('()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))');check('Cancelled narrow navigation retains draft and restores page focus',page.locator('.review-response [role=radio]').nth(1).get_attribute('aria-checked')=='true' and page.evaluate("document.activeElement.tagName!=='BODY'"))
